package Q6;
import javax.swing.*;import javax.swing.table.*;import java.awt.*;import java.sql.*;import java.util.*;
public class EventRegistrationApp extends JFrame{private final JTextField sid=new JTextField(12),name=new JTextField(12);private final JComboBox<String>event=new JComboBox<>(new String[]{"CULT01","TECH02"});private final DefaultTableModel model=new DefaultTableModel(new String[]{"ID","Student","Event","Registered"},0);private final JTable table=new JTable(model);private final String url=System.getenv().getOrDefault("DB_URL","jdbc:mysql://localhost:3306/campus_events"),user=System.getenv().getOrDefault("DB_USER","root"),pass=System.getenv().getOrDefault("DB_PASSWORD","");public EventRegistrationApp(){super("Campus Event Registration");JPanel form=new JPanel();form.add(new JLabel("Student ID"));form.add(sid);form.add(new JLabel("Name"));form.add(name);form.add(event);JButton register=new JButton("Register"),refresh=new JButton("Refresh");form.add(register);form.add(refresh);add(form,BorderLayout.NORTH);add(new JScrollPane(table),BorderLayout.CENTER);JMenuBar bar=new JMenuBar();JMenu file=new JMenu("File");JMenuItem exit=new JMenuItem("Exit");exit.addActionListener(e->dispose());file.add(exit);bar.add(file);setJMenuBar(bar);register.addActionListener(e->register());refresh.addActionListener(e->loadPage());setDefaultCloseOperation(EXIT_ON_CLOSE);setSize(750,450);setLocationRelativeTo(null);loadPage();}private Connection connect()throws SQLException{return DriverManager.getConnection(url,user,pass);}private void register(){String s=sid.getText().trim(),n=name.getText().trim(),ev=(String)event.getSelectedItem();if(s.isEmpty()||n.isEmpty()){JOptionPane.showMessageDialog(this,"Enter student ID and name");return;}new SwingWorker<Void,Void>(){protected Void doInBackground()throws Exception{try(Connection c=connect();PreparedStatement p=c.prepareStatement("INSERT INTO registrations(student_id,student_name,event_id,event_name) VALUES(?,?,?,?)")){p.setString(1,s);p.setString(2,n);p.setString(3,ev);p.setString(4,ev);p.executeUpdate();}return null;}protected void done(){try{get();JOptionPane.showMessageDialog(EventRegistrationApp.this,"Registration successful");loadPage();}catch(Exception ex){JOptionPane.showMessageDialog(EventRegistrationApp.this,"Registration failed (possibly duplicate): "+ex.getCause().getMessage());}}}.execute();}private void loadPage(){new SwingWorker<java.util.List<Object[]>,Void>(){protected java.util.List<Object[]>doInBackground()throws Exception{java.util.List<Object[]>rows=new ArrayList<>();try(Connection c=connect();PreparedStatement p=c.prepareStatement("SELECT registration_id,student_name,event_name,registered_at FROM registrations ORDER BY registration_id DESC LIMIT ? OFFSET ?")){p.setInt(1,50);p.setInt(2,0);try(ResultSet r=p.executeQuery()){while(r.next())rows.add(new Object[]{r.getLong(1),r.getString(2),r.getString(3),r.getTimestamp(4)});}}return rows;}protected void done(){try{model.setRowCount(0);for(Object[]r:get())model.addRow(r);}catch(Exception e){JOptionPane.showMessageDialog(EventRegistrationApp.this,"Load failed: "+e.getMessage());}}}.execute();}public static void main(String[]x){SwingUtilities.invokeLater(()->new EventRegistrationApp().setVisible(true));}}
